package at.hausgarten.service;

import org.json.*;
import java.io.IOException;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;

/** Read-only semantic validation of a captured financial namespace, independent of Android. */
final class LocalFinancialValidation {
    private static IOException invalid(String code){return new IOException("FINANCIAL_"+code);}
    private static void require(boolean value,String code)throws IOException{if(!value)throw invalid(code);}
    private static long integer(Object raw)throws Exception{try{return new BigDecimal(raw.toString()).longValueExact();}catch(Exception bad){throw invalid("AMOUNT_INVALID");}}
    private static BigDecimal quantity(Object raw)throws Exception{try{BigDecimal value=new BigDecimal(raw.toString());require(value.signum()>=0&&value.precision()<=24&&Math.abs(value.scale())<=12,"QUANTITY_INVALID");return value;}catch(NumberFormatException bad){throw invalid("QUANTITY_INVALID");}}
    private static JSONObject object(Object raw)throws Exception{return raw instanceof JSONObject?new JSONObject(raw.toString()):new JSONObject((String)raw);}
    private static String id(JSONObject row,String field)throws Exception{String value=row.getString(field);require(!value.trim().isEmpty(),"REFERENCE_INVALID");return value;}
    private static boolean issued(JSONObject invoice){return !invoice.optString("issued_at").isEmpty();}
    private static Map<String,JSONObject> index(JSONArray rows)throws Exception{Map<String,JSONObject> result=new HashMap<>();for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.getJSONObject(i);require(result.put(id(row,"id"),row)==null,"DUPLICATE_ID");}return result;}
    private static JSONObject find(Map<String,JSONObject> values,String id)throws Exception{JSONObject row=values.get(id);require(row!=null,"REFERENCE_MISSING");return row;}
    private static Map<String,JSONObject> records(JSONObject namespaces,String prefix)throws Exception{Map<String,JSONObject> result=new HashMap<>();for(Iterator<String> keys=namespaces.keys();keys.hasNext();){String key=keys.next();if(key.startsWith(prefix)){String suffix=key.substring(prefix.length());require(!suffix.isEmpty(),"NAMESPACE_INVALID");result.put(suffix,object(namespaces.get(key)));}}return result;}
    private static boolean same(JSONObject a,JSONObject b)throws Exception{return PixelMcpWriteTools.hash(a).equals(PixelMcpWriteTools.hash(b));}
    static boolean sameFrozenInvoice(JSONObject actual,JSONObject frozen)throws Exception{JSONObject first=new JSONObject(actual.toString()),second=new JSONObject(frozen.toString());for(String field:new String[]{"status","updated_at","payment_balance","pdf_state","pdf_sha256","pdf_storage_name","pdf_byte_size","pdf_base64","pdf_filename","document_id"}){first.remove(field);second.remove(field);}return same(first,second);}
    private static long invoiceMinor(JSONObject invoice)throws Exception{return invoice.optJSONObject("money_minor")!=null?integer(invoice.getJSONObject("money_minor").get("gross_minor")):LocalAuthorityRules.minor(invoice.has("gross_total")?invoice.get("gross_total"):invoice.get("amount"));}
    private static Map<String,Long> allocations(JSONObject payment,Map<String,JSONObject> invoices,boolean reversal)throws Exception{
        Map<String,Long> result=new TreeMap<>();JSONArray rows=payment.getJSONArray("allocations");require(rows.length()<=100,"PAYMENT_INVALID");for(int i=0;i<rows.length();i++){JSONObject allocation=rows.getJSONObject(i);String invoiceId=id(allocation,"invoice_id");JSONObject invoice=find(invoices,invoiceId);require(issued(invoice)&&invoiceMinor(invoice)>0,"PAYMENT_REFERENCE_INVALID");long amount=integer(allocation.get("amount_minor"));require(reversal?amount<0:amount>0,"PAYMENT_INVALID");require(result.put(invoiceId,amount)==null,"DUPLICATE_ALLOCATION");}return result;
    }
    private static void payments(Map<String,JSONObject> invoices,Map<String,JSONObject> payments,Map<String,JSONObject> opening)throws Exception{
        Map<String,String> reversed=new HashMap<>(),corrected=new HashMap<>();Map<String,Map<String,Long>> allocated=new HashMap<>();Set<String> requests=new HashSet<>(),clientRequests=new HashSet<>();
        for(Map.Entry<String,JSONObject> entry:payments.entrySet()){
            JSONObject row=entry.getValue();require(integer(row.get("formatVersion"))==1&&entry.getKey().equals(id(row,"payment_id")),"PAYMENT_INVALID");Instant.parse(row.getString("recorded_at"));boolean reversal=row.optBoolean("reversal");long amount=integer(row.get("amount_minor"));require(reversal?amount<0:amount>0,"PAYMENT_INVALID");Map<String,Long> allocation=allocations(row,invoices,reversal);allocated.put(entry.getKey(),allocation);long sum=0;for(long value:allocation.values())sum=Math.addExact(sum,value);
            if(reversal){String original=id(row,"reverses");require(!row.optString("reason").trim().isEmpty()&&reversed.put(original,entry.getKey())==null,"PAYMENT_CORRECTION_INVALID");}
            else{LocalDate.parse(row.getString("paid_on"));require(requests.add(id(row,"request_id")),"PAYMENT_DUPLICATE_REQUEST");if(row.has("client_request_id"))require(clientRequests.add(id(row,"client_request_id")),"PAYMENT_DUPLICATE_REQUEST");require(Arrays.asList("cash","bank","card","other").contains(row.optString("method")),"PAYMENT_INVALID");require(sum<=amount&&integer(row.get("unallocated_minor"))==amount-sum,"PAYMENT_SUM_MISMATCH");if(row.has("corrects")){String original=id(row,"corrects");require(!row.optString("reason").trim().isEmpty()&&corrected.put(original,entry.getKey())==null,"PAYMENT_CORRECTION_INVALID");}}
        }
        require(reversed.keySet().equals(corrected.keySet()),"PAYMENT_CORRECTION_INVALID");
        for(String originalId:reversed.keySet()){
            JSONObject original=find(payments,originalId),reversal=find(payments,reversed.get(originalId)),correction=find(payments,corrected.get(originalId));require(!original.optBoolean("reversal")&&!originalId.equals(correction.getString("payment_id"))&&reversal.getString("payment_id").equals(correction.getString("payment_id")+"_reversal"),"PAYMENT_CORRECTION_INVALID");require(integer(reversal.get("amount_minor"))==Math.negateExact(integer(original.get("amount_minor")))&&reversal.getString("reason").equals(correction.getString("reason")),"PAYMENT_CORRECTION_INVALID");Map<String,Long> expected=new TreeMap<>();for(Map.Entry<String,Long> allocation:allocated.get(originalId).entrySet())expected.put(allocation.getKey(),Math.negateExact(allocation.getValue()));require(expected.equals(allocated.get(reversal.getString("payment_id"))),"PAYMENT_CORRECTION_INVALID");
        }
        for(String start:corrected.keySet()){Set<String> visited=new HashSet<>();String next=start;while(corrected.containsKey(next)){require(visited.add(next),"PAYMENT_CORRECTION_INVALID");next=corrected.get(next);}}
        for(Map.Entry<String,JSONObject> entry:opening.entrySet()){JSONObject invoice=find(invoices,entry.getKey()),value=entry.getValue();long amount=integer(value.get("remaining_minor"));require(issued(invoice)&&amount>=0&&amount<=Math.max(0,invoiceMinor(invoice)),"OPENING_BALANCE_INVALID");if(value.has("invoice_id"))require(entry.getKey().equals(value.getString("invoice_id")),"OPENING_BALANCE_INVALID");}
    }
    private static void sourceLedger(String field,Map<String,JSONObject> ledger,Map<String,JSONObject> invoices,Map<String,JSONObject> sources,boolean material)throws Exception{
        Map<String,BigDecimal> totals=new HashMap<>();for(Map.Entry<String,JSONObject> entry:ledger.entrySet()){
            JSONObject invoice=find(invoices,entry.getKey());require(issued(invoice)&&!invoice.optString("local_issue_request").isEmpty()&&invoice.optJSONObject(field)!=null&&same(entry.getValue(),invoice.getJSONObject(field)),"SOURCE_SNAPSHOT_MISMATCH");JSONObject allocation=entry.getValue();for(Iterator<String> ids=allocation.keys();ids.hasNext();){String source=ids.next();Object raw=allocation.get(source);require(raw instanceof String,"QUANTITY_INVALID");BigDecimal amount=quantity(raw);require(amount.signum()>0,"QUANTITY_INVALID");JSONObject original=find(sources,source);BigDecimal available;
                if(material){require(original.optString("movement_kind").equals("consume"),"MATERIAL_REFERENCE_INVALID");available=new BigDecimal(original.getString("quantity_decimal")).abs();}else available=quantity(original.get("hours"));
                BigDecimal total=totals.getOrDefault(source,BigDecimal.ZERO).add(amount);require(total.compareTo(available)<=0,"SOURCE_QUANTITY_EXCEEDED");totals.put(source,total);boolean linked=false;JSONArray positions=invoice.getJSONArray("positions");for(int i=0;i<positions.length();i++){JSONObject line=positions.getJSONObject(i);if(material?line.optString("source_type").equals("material_movement")&&line.optString("source_id").equals(source):line.optString("worklog_id").equals(source)){require(new BigDecimal(line.get("quantity").toString()).compareTo(amount)==0,"SOURCE_SNAPSHOT_MISMATCH");if(material)require(line.optString("unit").equals(original.optString("unit")),"MATERIAL_REFERENCE_INVALID");linked=true;}}require(linked,"SOURCE_REFERENCE_INVALID");
            }
        }
        for(JSONObject invoice:invoices.values())if(issued(invoice)&&invoice.has(field))require(ledger.containsKey(invoice.getString("id")),"SOURCE_SNAPSHOT_MISMATCH");
    }
    private static void jobs(Map<String,JSONObject> invoices,Map<String,JSONObject> jobs)throws Exception{
        for(Map.Entry<String,JSONObject> entry:jobs.entrySet()){
            JSONObject job=entry.getValue(),invoice=find(invoices,entry.getKey()),frozen=job.getJSONObject("snapshot");String phase=job.getString("phase"),hash=job.getString("snapshot_sha256");require(integer(job.get("formatVersion"))==1&&entry.getKey().equals(id(job,"invoice_id"))&&entry.getKey().equals(id(frozen,"id")),"JOB_INVALID");require(Arrays.asList("PDF_PENDING","READY","ORIGINAL_REVIEW_REQUIRED").contains(phase)&&integer(job.opt("attempts")==null?0:job.get("attempts"))>=0,"JOB_INVALID");require(hash.matches("[0-9a-f]{64}")&&PixelMcpWriteTools.hash(frozen).equals(hash)&&issued(invoice)&&sameFrozenInvoice(invoice,frozen),"JOB_SNAPSHOT_MISMATCH");require(frozen.optString("pdf_state").equals("PDF_PENDING")&&same(frozen.getJSONObject("money_minor"),LocalAuthorityRules.exactTotals(frozen)),"JOB_SNAPSHOT_MISMATCH");
            require(frozen.optString("document_job_id").equals("invoice:"+entry.getKey())&&!frozen.optString("local_issue_request").isEmpty(),"JOB_INVALID");JSONObject issuer=frozen.getJSONObject("issuer"),recipient=frozen.getJSONObject("recipient");for(String field:new String[]{"owner_name","business_street","business_postal_code","business_city"})require(!issuer.optString(field).trim().isEmpty(),"JOB_SNAPSHOT_MISMATCH");for(String field:new String[]{"name","street","postal_code","city"})require(!recipient.optString(field).trim().isEmpty(),"JOB_SNAPSHOT_MISMATCH");require(Arrays.asList("small_business","standard").contains(frozen.optString("tax_mode")),"JOB_SNAPSHOT_MISMATCH");
            Instant.parse(frozen.getString("issued_at"));LocalDate invoiceDate=LocalDate.parse(frozen.getString("invoice_date")),start=LocalDate.parse(frozen.getString("service_start")),end=LocalDate.parse(frozen.getString("service_end"));require(!end.isBefore(start)&&!end.isAfter(invoiceDate),"JOB_SNAPSHOT_MISMATCH");
            if(phase.equals("READY")){JSONObject metadata=job.getJSONObject("document");require(invoice.optString("pdf_state").equals("READY")&&metadata.optString("document_id").equals("invoice:"+entry.getKey())&&metadata.optString("pdf_sha256").matches("[0-9a-f]{64}")&&metadata.optString("pdf_storage_name").equals(metadata.getString("pdf_sha256")+".pdf")&&integer(metadata.get("pdf_byte_size"))>0,"JOB_DOCUMENT_INVALID");for(String field:new String[]{"document_id","pdf_sha256","pdf_storage_name","pdf_byte_size"})require(metadata.get(field).toString().equals(invoice.get(field).toString()),"JOB_DOCUMENT_INVALID");}
            if(phase.equals("PDF_PENDING"))require(invoice.optString("pdf_state").equals("PDF_PENDING"),"JOB_INVALID");
        }
        for(JSONObject invoice:invoices.values())if(issued(invoice)&&!invoice.optString("local_issue_request").isEmpty())require(jobs.containsKey(invoice.getString("id")),"JOB_MISSING");
    }
    private static void numbers(JSONObject namespaces,Map<String,JSONObject> invoices,Map<String,JSONObject> jobs,Map<String,JSONObject> reservations)throws Exception{
        long high=0;Set<Long> counters=new HashSet<>();Set<String> reservedInvoices=new HashSet<>(),labels=new HashSet<>();
        for(JSONObject invoice:invoices.values())if(issued(invoice)&&!invoice.optString("invoice_number").isEmpty())require(labels.add(invoice.getString("invoice_number")),"NUMBER_COLLISION");
        for(Map.Entry<String,JSONObject> entry:reservations.entrySet()){
            JSONObject reservation=entry.getValue(),invoice=find(invoices,id(reservation,"invoice_id")),job=find(jobs,invoice.getString("id"));long counter=integer(reservation.get("counter"));require(integer(reservation.get("formatVersion"))==1&&entry.getKey().equals(reservation.getString("request_id"))&&entry.getKey().equals(invoice.getString("local_issue_request"))&&issued(invoice)&&counter>0&&counter<=1000000000L,"RESERVATION_INVALID");require(counters.add(counter)&&reservedInvoices.add(invoice.getString("id")),"NUMBER_COLLISION");require(reservation.getString("invoice_number").equals(invoice.getString("invoice_number"))&&reservation.getString("snapshot_sha256").equals(job.getString("snapshot_sha256")),"RESERVATION_SNAPSHOT_MISMATCH");JSONObject receipt=invoice.getJSONObject("numbering_receipt");require(receipt.optString("authority").equals(LocalAuthorityRules.ENGINE)&&receipt.getString("invoice_id").equals(invoice.getString("id"))&&receipt.getString("invoice_number").equals(invoice.getString("invoice_number"))&&integer(receipt.get("counter"))==counter&&receipt.getString("request_id").equals(entry.getKey()),"RESERVATION_SNAPSHOT_MISMATCH");high=Math.max(high,counter);
        }
        for(JSONObject invoice:invoices.values())if(issued(invoice)&&!invoice.optString("local_issue_request").isEmpty())require(reservations.containsKey(invoice.getString("local_issue_request")),"RESERVATION_MISSING");
        if(namespaces.has("local_invoice_external_evidence")){
            JSONObject proof=object(namespaces.get("local_invoice_external_evidence"));LocalAuthorityRules.requireEvidence(proof);long last=integer(proof.get("last_number"));require(last>=0&&last<=1000000000L,"COUNTER_INVALID");high=Math.max(high,last);Set<String> ids=new HashSet<>(),externalNumbers=new HashSet<>(),reservationIds=new HashSet<>();JSONArray originals=proof.getJSONArray("issued");
            for(int i=0;i<originals.length();i++){JSONObject original=originals.getJSONObject(i);String invoiceId=id(original,"invoice_id"),number=id(original,"invoice_number");require(ids.add(invoiceId)&&externalNumbers.add(number)&&original.optString("pdf_sha256").matches("[0-9a-f]{64}"),"NUMBER_EVIDENCE_INVALID");JSONObject known=invoices.get(invoiceId);if(known!=null){require(issued(known)&&number.equals(known.optString("invoice_number")),"NUMBER_EVIDENCE_INVALID");if(!known.optString("pdf_sha256").isEmpty())require(known.getString("pdf_sha256").equals(original.getString("pdf_sha256")),"NUMBER_EVIDENCE_INVALID");}else require(!labels.contains(number),"NUMBER_COLLISION");}
            JSONArray externalReservations=proof.getJSONArray("reservations");for(int i=0;i<externalReservations.length();i++){JSONObject reservation=externalReservations.getJSONObject(i);long counter=integer(reservation.get("counter"));require(reservationIds.add(id(reservation,"reservation_id"))&&counter>=0&&counter<=last&&Arrays.asList("reserved","issued","cancelled").contains(reservation.optString("state")),"NUMBER_EVIDENCE_INVALID");id(reservation,"invoice_id");id(reservation,"invoice_number");}
        }
        if(namespaces.has("local_invoice_counter")){long counter=integer(object(namespaces.get("local_invoice_counter")).get("last_number"));require(counter>=high&&counter>=0&&counter<=1000000000L,"COUNTER_INVALID");}else require(high==0,"COUNTER_MISSING");
    }
    static JSONObject inspect(JSONObject effective,JSONObject namespaces)throws Exception{
        try{
            Map<String,JSONObject> invoices=index(effective.optJSONArray("invoices")),work=index(effective.optJSONArray("worklogs"));Map<String,JSONObject> payments=records(namespaces,"local_payment:"),opening=records(namespaces,"invoice_opening_balance:"),jobs=records(namespaces,"local_invoice_job:"),reservations=records(namespaces,"local_number_reservation:"),workSources=records(namespaces,"local_invoice_sources:"),materials=records(namespaces,"local_invoice_material_sources:"),movements=records(namespaces,"revier:v1:entity:material_movement:");
            payments(invoices,payments,opening);sourceLedger("local_source_allocations",workSources,invoices,work,false);sourceLedger("local_material_source_allocations",materials,invoices,movements,true);jobs(invoices,jobs);numbers(namespaces,invoices,jobs,reservations);
            for(JSONObject invoice:invoices.values())if(issued(invoice)&&!invoice.optString("local_issue_request").isEmpty()&&!invoice.optString("document_type").equals("cancellation")){
                Set<String> works=new HashSet<>(),usedMaterial=new HashSet<>();JSONArray positions=invoice.getJSONArray("positions");for(int i=0;i<positions.length();i++){JSONObject line=positions.getJSONObject(i);String workId=line.optString("worklog_id");if(!workId.isEmpty())require(works.add(workId)&&workSources.containsKey(invoice.getString("id"))&&workSources.get(invoice.getString("id")).has(workId),"SOURCE_SNAPSHOT_MISMATCH");if(line.optString("source_type").equals("material_movement")){String movement=line.getString("source_id");require(usedMaterial.add(movement)&&materials.containsKey(invoice.getString("id"))&&materials.get(invoice.getString("id")).has(movement),"SOURCE_SNAPSHOT_MISMATCH");}}
            }
            for(JSONObject ledger:materials.values())for(Iterator<String> ids=ledger.keys();ids.hasNext();)require(!namespaces.has("revier:v1:reversed:"+ids.next()),"MATERIAL_REFERENCE_INVALID");
            return new JSONObject().put("formatVersion",1).put("status","PASS").put("counts",new JSONObject().put("payments",payments.size()).put("document_jobs",jobs.size()).put("number_reservations",reservations.size()).put("work_source_ledgers",workSources.size()).put("material_source_ledgers",materials.size())).put("original_files_verified",false).put("data_changed",false);
        }catch(IOException fixed){throw fixed;}catch(Exception malformed){throw invalid("RECORD_INVALID");}
    }
    private LocalFinancialValidation(){}
}
